import os, shutil, tempfile
from pathlib import Path
os.chdir(tempfile.mkdtemp())
for d in ('src/a', 'src/b', 'dest'):
    Path(d).mkdir(parents=True)
files = ('src/one.pdf', 'src/a/two.PDF',
         'src/b/three.txt', 'src/b/four.pdf')
for f in files: Path(f).write_text(f)
for folder, subs, files in os.walk('src'):
    for f in files:
        if f.lower().endswith('.pdf'):
            shutil.copy(Path(folder, f), 'dest')
print(sorted(os.listdir('dest')))
print(sorted(f for _, _, fs in os.walk('src') for f in fs))

import os, shutil, tempfile
from pathlib import Path
os.chdir(tempfile.mkdtemp())
Path('sub').mkdir()
sizes = {'big.bin': 3000, 'mid.bin': 1200,
         'tiny.txt': 40, 'sub/huge.bin': 9000}
for name, size in sizes.items():
    Path(name).write_bytes(b'x' * size)
found = {}
for folder, subs, files in os.walk('.'):
    for f in files:
        path = Path(folder, f)
# continued
        if os.path.getsize(path) > 1000:
            found[str(path)] = os.path.getsize(path)
print(dict(sorted(found.items(), key=lambda kv: -kv[1])))
